const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=v=>v===null||v===undefined||v===''?'未知':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:2});
const params=new URLSearchParams(location.search),type=params.get('type')||'card',id=params.get('id'),accountId=params.get('accountId');
async function api(path){const r=await fetch(path),j=await r.json();if(!r.ok)throw Error(j.error||'读取失败');return j}
const cell=(name,value,wide=false)=>`<div class="cell ${wide?'wide':''}"><small>${esc(name)}</small>${esc(value??'未知')}</div>`;
function title(name,sub){return`<h1>${esc(name)}</h1><div class="meta"><span>小木五简交易系统</span><span>${esc(sub)}</span><span>生成：${new Date().toLocaleString('zh-CN')}</span></div>`}
function cardPage(c){const p=c.plan?.payload||{},r=c.plan?.risk||{},w=c.water||{},layers=c.layers||{};return`${title('交易全流程卡',`${c.name} ${c.contract||c.symbol} · ${c.roundId}`)}<h2>火 · 机会证据</h2><div class="grid">${cell('来源',c.source)}${cell('模式',c.fire?.modeLabel)}${cell('数据截止',c.fire?.dataDate)}${cell('具体合约',c.contract)}${cell('方向',c.direction==='long'?'多头':'空头')}${cell('状态',c.status)}</div><h2>水 · 四问研究</h2><div class="grid">${cell('什么改变',w.change,true)}${cell('证据在哪里',w.evidence)}${cell('价格是否反映',w.pricedIn)}${cell('最强反证',w.disproof)}${cell('竞争解释',w.competingExplanation,true)}${cell('结论',w.conclusion,true)}</div><h2>金 · 五层与冻结计划</h2><div class="five">${['market','sector','month','week','day'].map((k,i)=>`<div><b>${['大盘','板块','月','周','日'][i]}</b><p>${esc(({long:'多头',short:'空头',neutral:'中性',unknown:'未知'})[layers[k]?.direction]||'未知')}</p><small>${esc(layers[k]?.source||'未填')}</small></div>`).join('')}</div><div class="grid">${cell('触发条件',p.trigger,true)}${cell('入场 / 止损',`${fmt(p.entry)} / ${fmt(p.stop)}`)}${cell('允许手数',fmt(r.lots))}${cell('冻结预算',fmt(r.frozenBudget))}${cell('价格范围',p.entryWindow)}${cell('有效期',p.validUntil)}${cell('退出规则',p.exitRule,true)}</div><h2>土 · 执行流水</h2>${table(c.executions||[],[['time','时间'],['externalId','标识'],['action','动作'],['status','状态'],['price','价格'],['quantity','数量']])}<h2>木 · 最近复盘</h2>${(c.reviews||[]).slice(0,3).map(x=>`<p><b>${esc(x.reviewType)}</b> ${esc(x.createdAt)}<br>做得好：${esc(x.payload.good||x.payload.executionConclusion)}<br>做得不好：${esc(x.payload.bad||x.payload.resultConclusion)}<br>下次注意：${esc(x.payload.next||x.payload.lessons)}</p>`).join('')||'<p class="muted">尚无复盘</p>'}`}
function table(rows,cols){if(!rows.length)return'<p class="muted">暂无记录</p>';return`<table><thead><tr>${cols.map(c=>`<th>${c[1]}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${cols.map(c=>`<td>${esc(row[c[0]]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function accountPage(summary){const a=summary.account;return`${title('账户风险总表',a.alias)}<h2>账户快照</h2><div class="grid">${cell('账户类型',a.mode)}${cell('风险档位',a.tier)}${cell('停机状态',a.stopped?'已停机':'未停机')}${cell('阶段本金',fmt(a.stageCapital))}${cell('实际权益',fmt(a.equity))}${cell('高水位',fmt(a.highWatermark))}${cell('恢复线',fmt(a.restoreLine))}${cell('已实现盈亏',fmt(a.realizedProfit))}${cell('保证金上限',fmt(a.marginLimit))}</div><h2>风险占用</h2><div class="grid">${cell('进行中交易卡',summary.openCount)}${cell('已批准',summary.approvedCount)}${cell('计划风险合计',fmt(summary.plannedRisk))}</div><h2>当前交易卡</h2>${table(summary.cards,[['name','品种'],['contract','合约'],['roundId','轮次'],['status','状态'],['direction','方向']])}<p class="muted">实际权益未知时，风险数字按阶段本金测算，不可替代实盘批准前核验。</p>`}
function reviewPage(c){return`${title('交易复盘记录',`${c.name} · ${c.roundId}`)}<div class="grid">${cell('本笔已实现净盈亏',fmt(c.trade?.realizedPnl))}${cell('交易结果',c.trade?.outcome)}${cell('本笔首次入账前 / 最后入账后',`${fmt(c.trade?.balanceBefore)} / ${fmt(c.trade?.balanceAfter)}`)}${cell('账户当前金额',fmt(c.account?.equity))}</div><h2>实际执行</h2>${table((c.executions||[]).map(x=>({...x,reason:x.payload.reason||'',netPnl:x.payload.netPnl,stop:x.payload.stop})),[['time','时间'],['action','动作'],['price','均价'],['quantity','手数'],['stop','保护价'],['reason','退出原因'],['netPnl','原始净盈亏']])}<h2>资金流水</h2>${table(c.trade?.ledger||[],[['kind','类型'],['amount','实际增减'],['balanceBefore','入账前'],['balanceAfter','入账后']])}<h2>复盘记录</h2>${(c.reviews||[]).map(r=>`<section><h2>${esc(r.createdAt)}</h2><div class="grid">${cell('哪些做得好',r.payload.good||r.payload.executionConclusion,true)}${cell('哪些做得不好',r.payload.bad||r.payload.resultConclusion,true)}${cell('下次注意什么',r.payload.next||r.payload.lessons,true)}</div></section>`).join('')||'<p class="muted">尚无复盘记录</p>'}`}
try{if(type==='account'){const s=await api(`/api/workbench/summary?accountId=${encodeURIComponent(accountId||'')}`);$('#paper').innerHTML=accountPage(s)}else{if(!id)throw Error('未选择交易卡');const c=await api(`/api/workbench/cards/${encodeURIComponent(id)}`);$('#paper').innerHTML=type==='review'?reviewPage(c):cardPage(c)}}catch(e){$('#paper').innerHTML=`<p class="error">${esc(e.message)}</p>`}
